name: Label dependencies

on:
  pull_request_target:
    types: [opened, reopened]

permissions:
  contents: read
  issues: write

jobs:
  add-dependencies-label:
    runs-on: ubuntu-latest
    if: "github.actor == 'dependabot[bot]' || github.actor == 'transifex-integration[bot]' || github.actor == 'imgbot[bot]'"
    steps:
      - name: Add :heavy_check_mark: dependencies label
        uses: actions/github-script@v7
        with:
          script: |
            const label = ':heavy_check_mark: dependencies';
            const { data: labels } = await github.rest.issues.listLabelsOnIssue({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });
            const hasLabel = labels.some(l => l.name === label);
            if (!hasLabel) {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                labels: [label]
              });
            }
